from datetime import datetime, timedelta, timezone
from functools import wraps

import jwt
from flask import request, g, current_app

from app.models.user import User


def create_token(user_id, role="user"):
    payload = {
        "sub": user_id,
        "role": role,
        "iat": datetime.now(timezone.utc),
        "exp": datetime.now(timezone.utc)
        + timedelta(hours=current_app.config["JWT_EXPIRATION_HOURS"]),
    }
    return jwt.encode(
        payload,
        current_app.config["SECRET_KEY"],
        algorithm=current_app.config["JWT_ALGORITHM"],
    )


def decode_token(token):
    return jwt.decode(
        token,
        current_app.config["SECRET_KEY"],
        algorithms=[current_app.config["JWT_ALGORITHM"]],
    )


def get_current_user():
    return g.get("current_user")


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        header = request.headers.get("Authorization")
        if not header or not header.startswith("Bearer "):
            return {"error": "Missing or invalid Authorization header"}, 401

        try:
            payload = decode_token(header.split(" ", 1)[1])
        except jwt.ExpiredSignatureError:
            return {"error": "Token has expired"}, 401
        except jwt.InvalidTokenError:
            return {"error": "Invalid token"}, 401

        user = User.get_by_id(payload["sub"])
        if not user:
            return {"error": "User not found"}, 401

        g.current_user = user
        return f(*args, **kwargs)

    return decorated


def require_role(*roles):

    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            user = get_current_user()
            if not user:
                return {"error": "Authentication required"}, 401
            if user.role not in roles:
                return {"error": "Insufficient permissions"}, 403
            return f(*args, **kwargs)

        return decorated

    return decorator

from typing import Optional

from pydantic import BaseModel, EmailStr, field_validator, Field


class LoginSchema(BaseModel):
    username: str = Field(..., min_length=1, max_length=80)
    password: str = Field(..., min_length=1, max_length=128)


class RegisterSchema(BaseModel):
    username: str = Field(..., min_length=3, max_length=80, pattern=r"^[a-zA-Z0-9_]+$")
    email: EmailStr
    password: str = Field(..., min_length=6, max_length=128)


class UserUpdateSchema(BaseModel):
    username: Optional[str] = Field(None, min_length=3, max_length=80, pattern=r"^[a-zA-Z0-9_]+$")
    email: Optional[EmailStr] = None
    password: Optional[str] = Field(None, min_length=6, max_length=128)
    role: Optional[str] = Field(None, pattern=r"^(user|admin)$")


class PaginationSchema(BaseModel):
    page: int = Field(1, ge=1)
    per_page: int = Field(20, ge=1, le=100)
    sort_by: Optional[str] = Field("id", pattern=r"^(id|username|email|role|created_at)$")
    order: Optional[str] = Field("asc", pattern=r"^(asc|desc)$")


def validate(schema_cls, data):

    try:
        return schema_cls(**data).model_dump(exclude_unset=True), None
    except Exception as e:
        return None, {"error": "Validation failed", "details": str(e)}

from flask import request, url_for

from app.config import Config


def paginate(items_fn, sort_by="id", order="asc"):

    page = request.args.get("page", Config.PAGINATION_DEFAULT_PAGE, type=int)
    per_page = request.args.get(
        "per_page", Config.PAGINATION_DEFAULT_PER_PAGE, type=int
    )
    if per_page > Config.PAGINATION_MAX_PER_PAGE:
        per_page = Config.PAGINATION_MAX_PER_PAGE
    if page < 1:
        page = 1

    items, total = items_fn(page=page, per_page=per_page, sort_by=sort_by, order=order)
    total_pages = (total + per_page - 1) // per_page if per_page > 0 else 0

    base_url = request.base_url
    links = {}

    if page > 1:
        links["prev"] = f"{base_url}?page={page - 1}&per_page={per_page}"
    if page < total_pages:
        links["next"] = f"{base_url}?page={page + 1}&per_page={per_page}"
    links["first"] = f"{base_url}?page=1&per_page={per_page}"
    links["last"] = f"{base_url}?page={total_pages}&per_page={per_page}"

    return {
        "items": [item.to_dict() for item in items],
        "meta": {
            "page": page,
            "per_page": per_page,
            "total": total,
            "total_pages": total_pages,
        },
        "links": links,
    }

from flask import jsonify


def handle_error(error, status_code=500):
    return (
        jsonify(
            {
                "error": {
                    "message": str(error),
                    "code": status_code,
                }
            }
        ),
        status_code,
    )


def register_error_handlers(app):

    @app.errorhandler(400)
    def bad_request(error):
        return jsonify({"error": {"message": str(error) or "Bad request", "code": 400}}), 400

    @app.errorhandler(401)
    def unauthorized(error):
        return jsonify({"error": {"message": str(error) or "Unauthorized", "code": 401}}), 401

    @app.errorhandler(403)
    def forbidden(error):
        return jsonify({"error": {"message": str(error) or "Forbidden", "code": 403}}), 403

    @app.errorhandler(404)
    def not_found(error):
        return jsonify({"error": {"message": str(error) or "Not found", "code": 404}}), 404

    @app.errorhandler(405)
    def method_not_allowed(error):
        return jsonify({"error": {"message": str(error) or "Method not allowed", "code": 405}}), 405

    @app.errorhandler(429)
    def ratelimit_error(error):
        return jsonify({"error": {"message": "Rate limit exceeded", "code": 429}}), 429

    @app.errorhandler(500)
    def internal_error(error):
        return jsonify({"error": {"message": "Internal server error", "code": 500}}), 500

from flask import Blueprint, request

from app.models.user import User
from app.utils.jwt import create_token, require_auth, require_role, get_current_user
from app.utils.validators import LoginSchema, RegisterSchema, UserUpdateSchema, validate
from app.middleware.audit import log_event

auth_bp = Blueprint("auth_v1", __name__, url_prefix="/api/v1/auth")


@auth_bp.route("/register", methods=["POST"])
def register():
    data, error = validate(RegisterSchema, request.get_json(silent=True) or {})
    if error:
        return error, 400

    try:
        user = User.create(
            username=data["username"],
            email=data["email"],
            password=data["password"],
        )
    except ValueError as e:
        return {"error": str(e)}, 409

    log_event("register", resource="user", resource_id=user.id, status_code=201)
    token = create_token(user.id, user.role)
    return {"user": user.to_dict(), "token": token}, 201


@auth_bp.route("/login", methods=["POST"])
def login():
    data, error = validate(LoginSchema, request.get_json(silent=True) or {})
    if error:
        return error, 400

    user = User.get_by_username(data["username"])
    if not user or not user.verify_password(data["password"]):
        log_event("login_failed", resource="auth", status_code=401)
        return {"error": "Invalid username or password"}, 401

    log_event("login", resource="user", resource_id=user.id, status_code=200)
    token = create_token(user.id, user.role)
    return {"user": user.to_dict(), "token": token}


@auth_bp.route("/me", methods=["GET"])
@require_auth
def me():
    user = get_current_user()
    return {"user": user.to_dict()}

